import{t as e}from"./link-C2W5MJHH.js";import{t}from"./jsx-runtime-NZYk81nU.js";import{t as n}from"./local-assets-D860wp0N.js";import{t as r}from"./arrow-up-right-DDS-tCIa.js";import{t as i}from"./book-open-CCYYJ7db.js";import{n as a,r as o}from"./PageHeader-towaNx_2.js";import{t as s}from"./button-DC4NoJ_F.js";var c=[{id:`heart-rate`,title:`What heart rate means`,tagline:`Your heartbeat is a window into fitness, stress and adaptation.`,minutes:4,diagram:`heart`,points:[{heading:`The basics`,body:`Heart rate is beats per minute (bpm). Each beat pushes blood carrying oxygen to your muscles and brain.`},{heading:`Resting vs active`,body:`Resting heart rate is measured when calm. It rises during exercise, stress, illness or dehydration and falls as you rest.`},{heading:`In space`,body:`Without gravity your heart pumps less hard to reach your head. Over months it may get slightly smaller, so trends matter more than single numbers.`}],quiz:[{q:`When should a resting heart rate be measured?`,options:[`Right after exercise`,`After 5 minutes of quiet rest`,`During an EVA`],answer:1,explain:`Resting rate is only comparable when taken in the same calm conditions.`},{q:`Why do trends matter more than one reading?`,options:[`Single readings are always wrong`,`Many things briefly change heart rate`,`Trends are easier to read`],answer:1,explain:`Caffeine, stress or movement can briefly change one reading. Trends show real adaptation.`}]},{id:`blood-pressure`,title:`How to measure blood pressure`,tagline:`Two numbers that describe how hard blood pushes on your arteries.`,minutes:5,diagram:`pressure`,points:[{heading:`Systolic & diastolic`,body:`Systolic (top) is pressure during a heartbeat. Diastolic (bottom) is pressure while the heart relaxes. Written like 118/76 mmHg.`},{heading:`Good technique`,body:`Rest 5 minutes, arm supported at heart level, cuff on bare skin, no talking. Bad position can change a reading by 10 mmHg or more.`},{heading:`Returning to gravity`,body:`After spaceflight, blood can pool in the legs when standing, causing dizziness. Pre-flight and in-flight trends help flight surgeons plan recovery.`}],quiz:[{q:`In 120/80, what is 80?`,options:[`Systolic`,`Diastolic`,`Heart rate`],answer:1,explain:`The bottom number is diastolic — pressure between beats.`},{q:`Where should your arm be during measurement?`,options:[`Above your head`,`At heart level`,`Hanging loose`],answer:1,explain:`Heart level avoids falsely high or low readings.`}]},{id:`oxygen`,title:`What oxygen saturation represents`,tagline:`How much of your blood's oxygen-carrying capacity is in use.`,minutes:3,diagram:`oxygen`,points:[{heading:`SpO₂`,body:`A pulse oximeter shines red and infrared light through your finger to estimate the % of haemoglobin carrying oxygen.`},{heading:`Typical readings`,body:`Healthy people at sea-level pressure usually read 95–100%. Your mission's reference range may differ.`},{heading:`Common errors`,body:`Cold fingers, movement, nail polish and poor fit can produce low readings. Always repeat an unexpected low value.`}],quiz:[{q:`What should you do with an unexpected low SpO₂ reading?`,options:[`Ignore it`,`Check sensor fit and repeat`,`Turn off the oximeter`],answer:1,explain:`Many low readings are caused by fit or cold hands. Repeat, then follow procedures if still low.`}]},{id:`sleep`,title:`Why sleep is important`,tagline:`Rest protects alertness, mood and safety-critical performance.`,minutes:4,diagram:`sleep`,points:[{heading:`Sleep cycles`,body:`Each night has ~4–5 cycles of light, deep and REM sleep. Deep sleep helps physical recovery; REM supports memory and mood.`},{heading:`Space disruptors`,body:`Noise from fans, light, 16 orbital sunrises and busy schedules mean astronauts often sleep ~6 hours.`},{heading:`Helpful habits`,body:`Keep a regular sleep time, dim screens, use eye masks and earplugs, and avoid caffeine late in the day.`}],quiz:[{q:`Which sleep stage especially supports memory and mood?`,options:[`REM sleep`,`Light sleep`,`Being awake`],answer:0,explain:`REM sleep is linked with memory consolidation and emotional processing.`}]},{id:`hydration`,title:`Why hydration matters`,tagline:`Thirst is a poor guide in microgravity.`,minutes:3,diagram:`water`,points:[{heading:`Less thirst`,body:`Fluid shifts toward the head trick the body into sensing it has extra fluid, so you may feel less thirsty.`},{heading:`Kidney stones`,body:`Bone calcium released in microgravity increases kidney stone risk. Drinking enough water helps flush it.`},{heading:`EVAs & exercise`,body:`Suits and exercise cause sweating. Hydrate before and after sessions.`}],quiz:[{q:`Why is kidney stone risk higher in space?`,options:[`More salt in food`,`Calcium released from bones`,`Cold water`],answer:1,explain:`Bone loss releases calcium that can form stones without enough fluid.`}]},{id:`microgravity`,title:`How microgravity affects the body`,tagline:`Fluids float up, muscles unload and balance gets confused.`,minutes:6,diagram:`microgravity`,points:[{heading:`Fluid shift`,body:`About 2 litres of fluid move from legs to head — 'puffy face, bird legs'. It can raise pressure around the eyes.`},{heading:`Balance`,body:`The inner ear loses its sense of 'down', which can cause space motion sickness in the first days.`},{heading:`Adaptation`,body:`The body adapts within weeks, then must readapt on return. Monitoring tracks both phases.`}],quiz:[{q:`What is the 'puffy face, bird legs' effect?`,options:[`Weight gain`,`Fluid shifting toward the head`,`Muscle growth`],answer:1,explain:`Without gravity pulling fluid down, it redistributes upward.`},{q:`What causes space motion sickness?`,options:[`Inner ear confusion`,`Radiation`,`Low oxygen`],answer:0,explain:`The vestibular system loses its gravity reference.`}]},{id:`bone-muscle`,title:`Bone and muscle changes`,tagline:`Use it or lose it — even in orbit.`,minutes:5,diagram:`bone`,points:[{heading:`Bone loss`,body:`Weight-bearing bones like hips and spine can lose around 1–1.5% of mass per month without loading.`},{heading:`Muscle loss`,body:`Postural muscles in legs and back weaken because they no longer hold you up.`},{heading:`Countermeasures`,body:`Daily resistance (ARED), cycling (CEVIS), treadmill (T2) and good nutrition greatly reduce losses.`}],quiz:[{q:`What is the main countermeasure for bone loss?`,options:[`Extra sleep`,`Resistance exercise`,`Drinking coffee`],answer:1,explain:`Mechanical loading through resistance exercise signals bones to stay strong.`}]},{id:`radiation`,title:`How radiation exposure is monitored`,tagline:`Invisible but measurable — dosimeters keep count.`,minutes:5,diagram:`radiation`,points:[{heading:`Sources`,body:`Galactic cosmic rays, solar particle events and trapped belt particles. Earth's magnetic field shields low orbit partly; the Moon and Mars have little protection.`},{heading:`Measuring dose`,body:`Personal and area dosimeters record dose in millisieverts (mSv). A typical ISS day is ~0.5–1 mSv; a chest X-ray is ~0.1 mSv.`},{heading:`Protection`,body:`Mission control warns of solar storms so crews can shelter in shielded areas. Cumulative dose is tracked against career limits.`}],quiz:[{q:`What unit is used for radiation dose?`,options:[`mmHg`,`Millisievert (mSv)`,`Kelvin`],answer:1,explain:`Sieverts measure the biological effect of radiation dose.`},{q:`Why is surface radiation higher on the Moon?`,options:[`It's closer to the Sun`,`No global magnetic field or thick atmosphere`,`Moon rocks are radioactive`],answer:1,explain:`Without a magnetic field or atmosphere, particles reach the surface.`}]},{id:`mental`,title:`Why mental wellbeing matters`,tagline:`Isolation and confinement test every crew.`,minutes:4,diagram:`mind`,points:[{heading:`Stressors`,body:`Isolation, confinement, distance from family, workload and the same faces every day can build up over months.`},{heading:`Noticing early`,body:`Regular check-ins help you notice changes in mood, energy or sleep before they affect you or the team.`},{heading:`Support`,body:`Breathing exercises, exercise, hobbies, private family calls and conversations with mission psychologists all help. Asking for support is a strength.`}],quiz:[{q:`Why do daily wellbeing check-ins help?`,options:[`They diagnose illness`,`They help notice changes early`,`They replace psychologists`],answer:1,explain:`Check-ins raise self-awareness; they do not diagnose.`}]}],l={version:1,asset_id:`095a1ee6-bdca-4b1a-8a0b-373b8d696b29`,project_id:`09550ea9-7589-4f06-857b-6266266615db`,url:`/__l5e/assets-v1/095a1ee6-bdca-4b1a-8a0b-373b8d696b29/human-research-image1.png`,r2_key:`a/v1/09550ea9-7589-4f06-857b-6266266615db/095a1ee6-bdca-4b1a-8a0b-373b8d696b29/human-research-image1.png`,original_filename:`human-research-image1.png`,size:89825,content_type:`image/png`,created_at:`2026-11-08T04:43:08Z`},u=t(),d=()=>(0,u.jsxs)(`div`,{className:`space-y-6`,children:[(0,u.jsx)(a,{kicker:`Learn`,title:`Education Centre`}),(0,u.jsx)(s,{asChild:!0,variant:`glass`,className:`h-auto w-full justify-start overflow-hidden whitespace-normal rounded-lg p-0 text-left`,children:(0,u.jsxs)(e,{to:`/learn/human-research`,className:`group flex flex-col sm:flex-row`,children:[(0,u.jsx)(`img`,{src:n(l,`human-research-image1.png`),alt:`Samantha Cristoforetti working in the Columbus module’s BioLab`,className:`h-48 w-full object-cover sm:h-44 sm:w-64`}),(0,u.jsxs)(`div`,{className:`flex min-w-0 flex-1 items-center gap-4 p-5`,children:[(0,u.jsxs)(`div`,{className:`min-w-0 flex-1`,children:[(0,u.jsxs)(`p`,{className:`mb-2 flex items-center gap-2 text-xs text-primary`,children:[(0,u.jsx)(i,{}),` Human spaceflight research`]}),(0,u.jsx)(`h2`,{className:`text-2xl font-semibold text-foreground`,children:`The Human Research`}),(0,u.jsx)(`p`,{className:`mt-2 text-sm leading-relaxed text-muted-foreground`,children:`NASA’s research into radiation, isolation, distance from Earth, gravity and closed environments.`}),(0,u.jsx)(`p`,{className:`mt-3 text-xs text-muted-foreground`,children:`5 spaceflight hazards · 6 NASA photographs`})]}),(0,u.jsx)(r,{className:`size-5 shrink-0 text-primary`})]})]})}),(0,u.jsx)(`div`,{className:`grid gap-4 md:grid-cols-2`,children:c.map(e=>(0,u.jsxs)(o,{kicker:`${e.minutes} min`,title:e.title,children:[(0,u.jsx)(`p`,{className:`mb-2 text-sm text-muted-foreground`,children:e.tagline}),e.points.map(e=>(0,u.jsxs)(`p`,{className:`text-sm`,children:[(0,u.jsxs)(`b`,{children:[e.heading,`:`]}),` `,e.body]},e.heading))]},e.id))})]});export{d as component};